dsl:
TEXT focus_1 "位置一" x=160 y=280
TEXT focus_2 "位置二" x=360 y=280
TEXT focus_3 "位置三" x=560 y=280
STYLE focus_1 {"alpha":1,"scale":1.15}
STYLE focus_2 {"alpha":0.45,"scale":1}
STYLE focus_3 {"alpha":0.45,"scale":1}
WAIT 500
STYLE focus_1 {"alpha":0.45,"scale":1}
STYLE focus_2 {"alpha":1,"scale":1.15}
WAIT 500
STYLE focus_2 {"alpha":0.45,"scale":1}
STYLE focus_3 {"alpha":1,"scale":1.15}

VAR focusIdx = 0
IMAGE patient_01 __01 x=120 y=200 w=120 h=160 z=3 vis=true
IMAGE patient_02 __02 x=340 y=200 w=120 h=160 z=3 vis=true
IMAGE patient_03 __03 x=560 y=200 w=120 h=160 z=3 vis=true
LOOP focusIdx < 3
    STYLE patient_01 {"alpha":1,"zIndex":10}
    STYLE patient_02 {"alpha":0.45,"zIndex":2}
    STYLE patient_03 {"alpha":0.45,"zIndex":2}
    WAIT 700
    STYLE patient_01 {"alpha":0.45,"zIndex":2}
    STYLE patient_02 {"alpha":1,"zIndex":10}
    WAIT 700
    STYLE patient_02 {"alpha":0.45,"zIndex":2}
    STYLE patient_03 {"alpha":1,"zIndex":10}
    WAIT 700
    VAR focusIdx + 1

IMAGE hint-icon __01 x=80 y=240 w=120 h=120 z=10 vis=true style={"alignCenter":true,"anchorX":0.5,"anchorY":0.5}
MOVE hint-icon 340 240 ms=800 keep=true
STYLE hint-icon {"alpha":0.6,"scale":1.3}

IF revealCount < 1
    IMAGE soap_reveal ___7 x=320 y=280 w=120 h=120 z=5 vis=true animation={"entry":{"animId":"___3"}}
    VAR revealCount + 1

IMAGE timer-preview-vegetable __01 x=320 y=185 w=160 h=160 z=20 vis=true
WAIT 600
TEXT timer-preview-tip "记住它的位置，倒计时马上开始！" x=210 y=410 block=false dismiss=true pad=12 style={"fontSize":"28","color":"#ffffff","stroke":"#000000","strokeThickness":2,"textAlign":"center","maxWidth":"400","zIndex":21}

TEXT focus-tip "当前焦点：请先查看药柜标签与服药顺序" x=240 y=180 block=false dismiss=true pad=0 style={"fontSize":"24","color":"#000000","stroke":"","strokeThickness":0,"dropShadow":false,"dropShadowColor":"#000000","dropShadowBlur":0,"dropShadowAngle":1.2,"dropShadowDistance":2,"maxWidth":"999","textAlign":"left"}
WAIT 800
TEXT_SET focus-tip "焦点切换：现在请确认第一剂药品的服用时间"

TEXT quick-score-label "得分：0" x=650 y=20 block=false dismiss=true style={"fontSize":28,"color":"#ffffff","stroke":"#000000","strokeThickness":2,"textAlign":"right","zIndex":100}
ON answer_correct "答对后更新得分"
    TEXT_SET quick-score-label "得分：10"

VAR tutorial_done = 0
TEXT hotpot_tutorial_hint "点选食材，回忆老火锅味道" x=200 y=480 block=false style={"fontSize":22,"color":"#fff4e0"}
CLICK hotpot_tutorial_hint enabled=true block=false action=commands
    VAR tutorial_done = 1
    STYLE hotpot_tutorial_hint {"display":"none"}

IMAGE score-bonus-check check-circle x=360 y=220 w=48 h=48 z=20 vis=true
MOVE score-bonus-check 680 70 ms=400 keep=true
STYLE score-bonus-check {"scale":1.3,"alpha":0.9}

TEXT level-clear-status "正在核对通关结果…" x=360 y=220 style={"fontSize":30,"color":"#ffffff","textAlign":"center"}
ON result_checked "结果核对完成"
    TEXT_SET level-clear-status "挑战完成！各就各位，顺利通关！"

VAR "焦点目标" = "蝴蝶"
IF "焦点目标" == "蝴蝶"
    IMAGE focus-butterfly ___7 x=350 y=250 w=120 h=100 z=50 vis=true animation={"entry":{"animId":"___3"}}
ELSE
    IMAGE focus-bug ___2 x=350 y=250 w=77 h=52 z=50 vis=true animation={"entry":{"animId":"___4"}}

TEXT medication-score-text "本轮得分：0" x=580 y=24 block=false dismiss=true pad=12 style={"fontSize":28,"color":"#ffffff","stroke":"#000000","strokeThickness":2,"textAlign":"right","maxWidth":"200","zIndex":100}
ON answer_correct "答对后更新得分"
    TEXT_SET medication-score-text "本轮得分：10"

TEXT focus-prompt "汤底香气渐浓" x=360 y=180 block=false dismiss=false pad=20 style={"fontSize":"32","color":"#fff3d6","stroke":"#5b1e12","strokeThickness":2,"dropShadow":true,"dropShadowColor":"#000000","dropShadowBlur":1,"dropShadowAngle":1.2,"dropShadowDistance":2,"maxWidth":600,"textAlign":"center","zIndex":120}
WAIT 800
TEXT_SET focus-prompt "请把注意力转向沸腾的锅中央"

IMAGE brown_drug_01 _____16 x=300 y=200 w=80 h=80 z=5 vis=true
MOVE brown_drug_01 500 150
STYLE brown_drug_01 {"scale":1.2,"alpha":0.9}

IMAGE combo-fruit _06 x=360 y=300 w=80 h=80 z=20 vis=true
MOVE combo-fruit 360 180 ms=400 keep=true
STYLE combo-fruit {"scale":1.25,"alpha":0.85}

IMAGE focus1 ___10 x=200 y=150 vis=true
STYLE focus1 {"tint":"0xff0000","alpha":1}
IMAGE focus2 ___9 x=400 y=150 vis=true
STYLE focus2 {"tint":"0x00ff00","alpha":1}

IMAGE wrong-feedback-card _____11 x=250 y=-160 w=300 h=180 z=20 vis=true
MOVE wrong-feedback-card 250 190 ms=350 keep=true
STYLE wrong-feedback-card {"alpha":0.7}

TEXT reveal_text "探索新资源" x=100 y=100 size={"width":200,"height":50}
ON resource_found "发现资源"
    TEXT_SET reveal_text "发现隐藏资源已激活"

IMAGE ambient-butterfly ___7 x=90 y=440 w=100 h=80 z=5 vis=true
MOVE ambient-butterfly 620 120 ms=1800 keep=true
STYLE ambient-butterfly {"scale":0.7,"alpha":0.55}

IMAGE exit-success-card _____10 x=200 y=110 w=400 h=300 z=20 vis=true
WAIT 800
TEXT exit-message "本轮分类完成，准备进入下一环节" x=190 y=440 style={"fontSize":28,"color":"#ffffff","zIndex":21}

IMAGE intro-panel intro-____ x=0 y=0 w=800 h=600 vis=true
WAIT 1000
TEXT score-text "分数 +10" x=400 y=300 style={"fontSize":36,"color":"#ffff00"}

IMAGE ambient_butterfly ___7 x=80 y=120 w=80 h=60 z=5 vis=true
MOVE ambient_butterfly 620 180 ms=2500 keep=true
STYLE ambient_butterfly {"alpha":0.55}

IMAGE note_card __01 x=250 y=150 w=300 h=200 z=10 vis=true
WAIT 1000
TEXT hint_text "记住这张便签上的内容，准备开始计时" x=200 y=400 style={"fontSize":22,"color":"#ffffff"}

IMAGE ambient_vegetable __01 x=60 y=440 vis=true
MOVE ambient_vegetable 620 80 ms=1600 keep=true
STYLE ambient_vegetable {"alpha":0.72,"scale":0.88}

IMAGE progress_panel ____01 x=200 y=120 w=400 h=300 z=10 vis=true
WAIT 800
TEXT progress_tip "进度已更新：本关咨询步骤完成 1/3，请继续核对药品信息" x=120 y=450 style={"fontSize":22,"color":"#ffffff","maxWidth":560,"textAlign":"center","zIndex":20}

IMAGE progress-complete-mark check-circle x=704 y=48 w=48 h=48 z=20 vis=true
STYLE progress-complete-mark {"alpha":0.5}
STYLE progress-complete-mark {"alpha":1,"scale":1.15}

IMAGE score-feedback-item __01 x=360 y=300 w=72 h=72 z=20 vis=true
MOVE score-feedback-item 650 70 ms=450 keep=true
STYLE score-feedback-item {"scale":0.45,"alpha":0.35}

IMAGE focus_bun ____1 x=300 y=150
WAIT 700
TEXT focus_hint "请把注意力转向小笼包" x=240 y=420 style={"fontSize":28,"color":"#ffffff"}

IMAGE refresh-hint-card __01_2 x=260 y=155 w=280 h=210 z=20 vis=true
STYLE refresh-hint-card {"alpha":0.5}
STYLE refresh-hint-card {"alpha":1,"zIndex":30}

IMAGE combo_pill _____13 x=350 y=280 w=80 h=80 z=50 vis=true style={"alpha":0.55}
MOVE combo_pill 350 120 ms=400 keep=true
STYLE combo_pill {"scale":1.4,"alpha":1}

TEXT clue-reveal-message "角落里出现了一张新的食材线索！" x=180 y=120 block=false dismiss=true style={"fontSize":28,"color":"#ffffff"}
WAIT 900
CHOICES clue-reveal-options x=220 y=260 block=true multi=false ui={"rowMax":2,"gapX":16,"gapY":12,"minWidth":30,"fontSize":24,"maxWidth":300,"paddingX":20,"paddingY":12,"color":"#ffffff","zIndex":100}
    OPTION option_1 "查看线索"
    OPTION option_2 "继续寻找"

CHOICES show_choices_tutorial_hint x=200 y=360 block=true multi=false ui={"rowMax":2,"gapX":24,"gapY":16,"minWidth":120,"fontSize":24,"maxWidth":320,"paddingX":16,"paddingY":12,"color":"#ffffff","zIndex":130}
    OPTION understood "我知道了"
    OPTION replay "再看一遍"

IMAGE hongshu-reveal ___8 x=80 y=420 w=100 h=100 z=12 vis=true style={"alpha":0.55}
MOVE hongshu-reveal 340 270 ms=800 keep=true
STYLE hongshu-reveal {"scale":1.35,"alpha":1}

IMAGE progress-check check-circle x=120 y=480 w=72 h=72 z=30 vis=true style={"alpha":0.55}
MOVE progress-check 360 80 ms=450 keep=true
STYLE progress-check {"scale":1.25,"alpha":1,"zIndex":40}

IMAGE sync_pill _____14 x=120 y=360 w=90 h=90 z=20 vis=true style={"alpha":0.55}
MOVE sync_pill 400 220 ms=600 keep=true
STYLE sync_pill {"scale":1.25,"alpha":1,"zIndex":30}

CHOICES beat_start_choice x=280 y=360 block=true multi=false ui={"rowMax":1,"gapX":16,"gapY":12,"minWidth":160,"fontSize":26,"maxWidth":260,"paddingX":20,"paddingY":14,"color":"#ffffff","zIndex":100}
    OPTION start "开始这一拍"
        VAR "计时节拍" = 1

CHOICES show_choices_wrong_fb x=200 y=280 block=true multi=false ui={"rowMax":1,"gapX":16,"gapY":20,"minWidth":120,"fontSize":28,"maxWidth":360,"paddingX":20,"paddingY":14,"color":"#ffffff","zIndex":130}
    OPTION retry "再试一次"
    OPTION hint "查看提示"

IMAGE correct_feedback_icon check-circle x=360 y=620 w=80 h=80 z=50 vis=true
MOVE correct_feedback_icon 360 260 ms=600 keep=true
STYLE correct_feedback_icon {"scale":1.25,"alpha":1}

IMAGE reveal_vegetable "蔬菜01" x=90 y=80 w=100 h=100 z=10 vis=true
MOVE reveal_vegetable 350 260 ms=800 keep=true
STYLE reveal_vegetable {"scale":1.15}

IMAGE victory_panel "胜利弹窗2" x=250 y=620 vis=true
MOVE victory_panel 250 170 ms=700 keep=true
STYLE victory_panel {"scale":1.08,"alpha":1}

IMAGE blue_medicine_reveal "模板1难度二4-6关新增蓝色药" x=80 y=220 w=120 h=120 z=10 vis=true
STYLE blue_medicine_reveal {"alpha":0.45}
MOVE blue_medicine_reveal 340 220 ms=800 keep=true
STYLE blue_medicine_reveal {"alpha":1,"scale":1.15}

IMAGE combo_celebrate_question "问号" x=360 y=260 w=80 h=80 vis=true
MOVE combo_celebrate_question 620 110 ms=400 keep=true
STYLE combo_celebrate_question {"scale":1.25,"alpha":1}

IMAGE correct_feedback_icon check-circle x=360 y=80 w=80 h=80 vis=true
MOVE correct_feedback_icon 360 260 ms=600 keep=true
STYLE correct_feedback_icon {"alpha":1,"scale":1.25}

IMAGE score_ingredient "食材01" x=60 y=440 vis=true
STYLE score_ingredient {"alpha":0.4}
MOVE score_ingredient 650 110 ms=700 keep=true
STYLE score_ingredient {"alpha":1}

IMAGE combo_celebration_star star x=60 y=440 vis=true
MOVE combo_celebration_star 360 260 ms=500 keep=true
STYLE combo_celebration_star {"scale":1.35,"alpha":1}
